const search = document.querySelector('#search');
const result = document.querySelector('#result');

search.addEventListener('input', () => {
  result.textContent = `${search.value.length}글자`;
});

const search = document.querySelector('#search');
const result = document.querySelector('#result');

search.addEventListener('input', () => {
  if (search.value === '') {
    result.textContent = '전체 코스';
  } else {
    result.textContent = `검색어: ${search.value}`;
  }
});
